{
  "name": "SCPI 网络通信组件",
  "name_en": "SCPI Network Communication Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于通过 IP 与支持 SCPI/IEEE 488.2 的仪器交互。它提供通用命令发送、状态寄存器读写、身份查询、触发、复位以及二进制块传输等能力，常用于实验系统中统一接入不同型号的网络仪器。",
  "description_en": "This is a non-physical software communication component for interacting with SCPI/IEEE 488.2 compliant instruments over IP. It provides generic command/query handling, status register access, identity queries, triggering, reset, and binary block transfer, and is commonly used to integrate different networked instruments in laboratory setups.",
  "tag_hints": [
    "SCPI",
    "IEEE 488.2",
    "instrument communication",
    "TCP/IP instrument control",
    "status registers",
    "binary block transfer"
  ],
  "actions": [
    {
      "action_name": "auto-ask_float",
      "description": "发送 SCPI 查询并将结果解析为浮点数",
      "description_en": "Send a SCPI query and parse the reply as a float."
    },
    {
      "action_name": "auto-ask_int",
      "description": "发送 SCPI 查询并将结果解析为整数",
      "description_en": "Send a SCPI query and parse the reply as an integer."
    },
    {
      "action_name": "auto-bin_block_read",
      "description": "读取 IEEE 488.2 二进制块数据",
      "description_en": "Read an IEEE 488.2 binary block."
    },
    {
      "action_name": "auto-bin_block_write",
      "description": "写入 IEEE 488.2 二进制块数据",
      "description_en": "Write an IEEE 488.2 binary block."
    },
    {
      "action_name": "auto-clear_status",
      "description": "清除状态",
      "description_en": "Clear status."
    },
    {
      "action_name": "auto-operation_complete",
      "description": "获取操作完成状态",
      "description_en": "Get operation complete status."
    },
    {
      "action_name": "auto-reset",
      "description": "复位 SCPI 会话或设备状态",
      "description_en": "Reset the SCPI session or device state."
    },
    {
      "action_name": "auto-service_request_enable",
      "description": "设置服务请求使能寄存器",
      "description_en": "Set the service request enable register."
    },
    {
      "action_name": "auto-set_event_status_enable",
      "description": "设置事件状态使能寄存器",
      "description_en": "Set the event status enable register."
    },
    {
      "action_name": "auto-trigger",
      "description": "发送触发命令",
      "description_en": "Send a trigger command."
    },
    {
      "action_name": "auto-wait",
      "description": "等待当前操作完成",
      "description_en": "Wait for the current operation to complete."
    },
    {
      "action_name": "auto-get_event_status_enable",
      "description": "获取事件状态使能寄存器",
      "description_en": "Get the event status enable register."
    },
    {
      "action_name": "auto-get_event_status_enable_register",
      "description": "获取事件状态使能寄存器值",
      "description_en": "Get the event status enable register value."
    },
    {
      "action_name": "auto-get_identity",
      "description": "获取设备标识",
      "description_en": "Get the device identity."
    },
    {
      "action_name": "auto-get_operation_complete",
      "description": "获取操作完成状态",
      "description_en": "Get operation complete status."
    },
    {
      "action_name": "auto-get_options",
      "description": "获取已安装选件",
      "description_en": "Get installed options."
    },
    {
      "action_name": "auto-get_service_request_enable",
      "description": "获取服务请求使能寄存器",
      "description_en": "Get the service request enable register."
    },
    {
      "action_name": "auto-get_status_byte",
      "description": "获取状态字节",
      "description_en": "Get the status byte."
    },
    {
      "action_name": "auto-get_test_result",
      "description": "获取自检结果",
      "description_en": "Get the self-test result."
    },
    {
      "action_name": "auto-get_error",
      "description": "获取系统错误信息",
      "description_en": "Get the system error message."
    },
    {
      "action_name": "auto-get_system_error_count",
      "description": "获取系统错误计数",
      "description_en": "Get the system error count."
    },
    {
      "action_name": "auto-get_system_version",
      "description": "获取系统版本",
      "description_en": "Get the system version."
    }
  ]
}

